"""OpenType feature source (GSUB).  kern / mark / mkmk / GDEF are generated by
ufo2ft from the kerning, groups and anchors stored in each master."""
from __future__ import annotations
import unicodedata
from . import marks
from .symbols import FIGS

VIET = [((0x302, 0x301), 'circumflexcomb', 'acutecomb'), ((0x302, 0x300), 'circumflexcomb', 'gravecomb'),
        ((0x302, 0x309), 'circumflexcomb', 'hookabovecomb'), ((0x302, 0x303), 'circumflexcomb', 'tildecomb'),
        ((0x306, 0x301), 'brevecomb', 'acutecomb'), ((0x306, 0x300), 'brevecomb', 'gravecomb'),
        ((0x306, 0x309), 'brevecomb', 'hookabovecomb'), ((0x306, 0x303), 'brevecomb', 'tildecomb')]

CASE_PAIRS = ['hyphen', 'endash', 'emdash', 'parenleft', 'parenright', 'bracketleft', 'bracketright', 'braceleft',
              'braceright', 'colon', 'guilsinglleft', 'guilsinglright', 'guillemotleft', 'guillemotright',
              'periodcentered', 'bullet', 'exclamdown', 'questiondown', 'at']


def cls(names, per=12):
    out = []
    for i in range(0, len(names), per):
        out.append(' '.join(names[i:i + per]))
    return '[' + '\n    '.join(out) + ']'


def build_features(glyphs, cmap):
    names = list(glyphs)
    has = set(names)
    rev = {}
    for cp, n in cmap.items():
        rev.setdefault(n, []).append(cp)
    upper = [n for n in names if any(unicodedata.category(chr(c)) == 'Lu' for c in rev.get(n, [])) or n.endswith('.ss01')]
    lc_above = [n for n in sorted(marks.MARKS) if not n.endswith('.case') and (n + '.case') in has
                and n not in ('tonoscomb', 'dieresistonoscomb', 'horncomb')]
    case_above = [n + '.case' for n in lc_above]
    comb_above = [n for n in sorted(marks.MARKS) if not n.endswith(('.case', '.alt')) and 'top' in getattr(glyphs[n], 'anchors', {})
                  and '_top' in glyphs[n].anchors]
    comb_below = [n for n in sorted(marks.MARKS) if '_bottom' in glyphs[n].anchors or '_ogonek' in glyphs[n].anchors]
    figs = FIGS
    tf = [f + '.tf' for f in figs]
    numr = [f + '.numr' for f in figs]; dnom = [f + '.dnom' for f in figs]
    sups = [f + '.sups' for f in figs]; subs = [f + '.subs' for f in figs]
    allfig = figs + tf + ['zero.zero', 'zero.zero.tf']
    L = []
    A = L.append
    A('# Orion — OpenType layout features (generated by sources/build-scripts; edit the generator, not this file)')
    for ls in ('DFLT dflt', 'latn dflt', 'latn ROM', 'latn MOL', 'latn CAT', 'grek dflt', 'cyrl dflt', 'cyrl SRB', 'cyrl MKD'):
        A('languagesystem %s;' % ls)
    A('')
    A('@Upper = %s;' % cls(upper))
    A('@MarkAboveLC = %s;' % cls(lc_above))
    A('@MarkAboveCase = %s;' % cls(case_above))
    A('@CombAbove = %s;' % cls(comb_above))
    A('@CombBelow = %s;' % cls(comb_below))
    A('@Fig = %s;' % cls(figs)); A('@FigTab = %s;' % cls(tf))
    A('@FigAll = %s;' % cls(allfig))
    A('@Numr = %s;' % cls(numr)); A('@Dnom = %s;' % cls(dnom))
    A('@Sups = %s;' % cls(sups)); A('@Subs = %s;' % cls(subs))
    A('')
    # ---- ccmp
    A('feature ccmp {')
    A('  lookup ccmp_viet {')
    for cps, a, b in VIET:
        A('    sub %s %s by uni%04X%04X;' % (a, b, cps[0], cps[1]))
    A('  } ccmp_viet;')
    A('  lookup ccmp_dotless {')
    for src, dst in (('i', 'dotlessi'), ('j', 'dotlessj'), ('uni0456', 'dotlessi'), ('uni0458', 'dotlessj')):
        A("    sub %s' @CombAbove by %s;" % (src, dst))
        A("    sub %s' @CombBelow @CombAbove by %s;" % (src, dst))
    A('  } ccmp_dotless;')
    A('  lookup ccmp_case {')
    A("    sub @Upper @MarkAboveLC' by @MarkAboveCase;")
    A("    sub @Upper @CombBelow @MarkAboveLC' by @MarkAboveCase;")
    A("    sub @MarkAboveCase @MarkAboveLC' by @MarkAboveCase;")
    A("    sub @Upper horncomb' by horncomb.case;")
    A('  } ccmp_case;')
    A('} ccmp;')
    A('')
    # ---- locl
    A('feature locl {')
    A('  script latn;')
    for lang in ('ROM', 'MOL'):
        A('  language %s;' % lang)
        A('    sub uni015E by uni0218; sub uni015F by uni0219; sub uni0162 by uni021A; sub uni0163 by uni021B;')
    A('  language CAT;')
    A("    sub l periodcentered' l by periodcentered.loclCAT;")
    A("    sub L periodcentered' L by periodcentered.loclCAT.case;")
    A('  script cyrl;')
    for lang in ('SRB', 'MKD'):
        A('  language %s;' % lang)
        A('    sub uni0431 by uni0431.loclSRB;')
    A('} locl;')
    A('')
    # ---- numerals
    A('feature pnum {\n  sub @FigTab by @Fig;\n  sub zero.zero.tf by zero.zero;\n  sub period.tf by period; sub comma.tf by comma; sub colon.tf by colon; sub colon.case.tf by colon.case;\n} pnum;')
    A('feature tnum {\n  sub @Fig by @FigTab;\n  sub zero.zero by zero.zero.tf;\n  sub period by period.tf; sub comma by comma.tf; sub colon by colon.tf; sub colon.case by colon.case.tf;\n} tnum;')
    A('feature zero {\n  sub zero by zero.zero;\n  sub zero.tf by zero.zero.tf;\n} zero;')
    A('feature numr {\n  sub @Fig by @Numr;\n  sub @FigTab by @Numr;\n} numr;')
    A('feature dnom {\n  sub @Fig by @Dnom;\n  sub @FigTab by @Dnom;\n} dnom;')
    A('feature sups {\n  sub @Fig by @Sups;\n  sub @FigTab by @Sups;\n} sups;')
    A('feature subs {\n  sub @Fig by @Subs;\n  sub @FigTab by @Subs;\n} subs;')
    A('feature sinf {\n  sub @Fig by @Subs;\n  sub @FigTab by @Subs;\n} sinf;')
    # contextual fractions: 1/2 -> numerators, fraction bar, denominators
    A('feature frac {')
    A('  lookup frac_bar {')
    A("    sub @FigAll slash' @FigAll by fraction;")
    A('  } frac_bar;')
    # one lookup per numerator digit: each lookup is a separate pass over the run
    A('  lookup frac_numr1 {')
    A("    sub @Fig' fraction by @Numr;")
    A("    sub @FigTab' fraction by @Numr;")
    A('  } frac_numr1;')
    for k in range(1, 6):
        ctx = ' '.join(['@Numr'] * k)
        A('  lookup frac_numr%d {' % (k + 1))
        A("    sub @Fig' %s fraction by @Numr;" % ctx)
        A("    sub @FigTab' %s fraction by @Numr;" % ctx)
        A('  } frac_numr%d;' % (k + 1))
    A('  lookup frac_dnom {')
    A("    sub fraction @Fig' by @Dnom;")
    A("    sub fraction @FigTab' by @Dnom;")
    A("    sub @Dnom @Fig' by @Dnom;")
    A("    sub @Dnom @FigTab' by @Dnom;")
    A('  } frac_dnom;')
    A('} frac;')
    A("feature ordn {\n  sub @FigAll [a o]' by [ordfeminine ordmasculine];\n} ordn;")
    A('')
    # ---- case
    A('feature case {')
    for n in CASE_PAIRS:
        if n + '.case' in has:
            A('  sub %s by %s.case;' % (n, n))
    A('  sub colon.tf by colon.case.tf;')
    A('} case;')
    A('')
    # ---- contextual: colons between figures centre on the figures (timers)
    A('feature calt {')
    A("  sub @FigAll colon' @FigAll by colon.case;")
    A("  sub @FigAll colon.tf' @FigAll by colon.case.tf;")
    A('} calt;')
    A('')
    # ---- stylistic sets
    for tag, suf, label in (('ss01', '.ss01', 'Serifed capital I'), ('ss02', '.ss02', 'Plain l without tail'),
                            ('ss03', '.ss03', 'Single-storey a')):
        pairs = [(n[:-len(suf)], n) for n in names if n.endswith(suf) and n[:-len(suf)] in has]
        A('feature %s {' % tag)
        A('  featureNames { name "%s"; };' % label)
        for a, b in pairs:
            A('  sub %s by %s;' % (a, b))
        A('} %s;' % tag)
    A('')
    return '\n'.join(L) + '\n'
